vector<int> bfs01(const vector<vector<pair<int,int>>>& g, int s) {
    vector<int> d(g.size(), INT_MAX);
    deque<int> dq;
    d[s] = 0; dq.push_back(s);
    while (!dq.empty()) {
        int u = dq.front(); dq.pop_front();
        for (auto [v, w] : g[u]) {
            if (d[u] + w < d[v]) {
                d[v] = d[u] + w;
                if (w == 1) dq.push_front(v);
                else dq.push_back(v);
            }
        }
    }
    return d;
}
